 const messages=[];let current=null;
 try {for(const frame of frames){if(frame.opcode>=8)continue;if(frame.opcode===1||frame.opcode===2){assert.equal(current,null);current={opcode:frame.opcode,compressed:frame.rsv1,parts:[]};}else assert.equal(frame.opcode,0);assert.ok(current);current.parts.push(Buffer.from(frame.payloadBase64,'base64'));if(!frame.fin)continue;let decoded=Buffer.concat(current.parts);if(current.compressed){emitted=[];await new Promise((resolve,reject)=>{const onError=error=>reject(error);inflate.once('error',onError);inflate.write(Buffer.concat([decoded,Buffer.from([0,0,255,255])]));inflate.flush(Z.Z_SYNC_FLUSH,error=>{inflate.off('error',onError);error?reject(error):resolve();});});if(failure)throw failure;decoded=Buffer.concat(emitted);}messages.push({opcode:current.opcode,compressed:current.compressed,text:decoded.toString('utf8'),decodedBase64:decoded.toString('base64')});current=null;}assert.equal(current,null);return messages;}finally{inflate.destroy();}
