  const clients=[];const sockets=new Set();const observerIn=frameObserver(record.inboundFrames);const observerOut=frameObserver(record.outboundFrames,{httpHead:true});
  const ws=new WebSocketServer({noServer:true,perMessageDeflate:{threshold:0}});
