   const write=socket.write;socket.write=function(chunk,...rest){const bytes=Buffer.isBuffer(chunk)?chunk:Buffer.from(chunk,typeof rest[0]==='string'?rest[0]:'utf8');record.rawOutgoing.push(bytes.toString('base64'));observerOut.feed(bytes);return write.call(this,chunk,...rest)};
