  ws.on('connection',client=>{clients.push(client);record.negotiatedExtensions=client.extensions;client.on('error',error=>record.peerError=error.message);client.on('message',(data,isBinary)=>{const value=JSON.parse(data.toString());record.received.push({isBinary,value});if(channel==='homeassistant'){if(value.type==='auth')client.send(JSON.stringify({type:'auth_ok',ha_version:'fixture'}),{compress:true});else if(value.type==='subscribe_events'||value.type==='call_service')client.send(JSON.stringify({id:value.id,type:'result',success:true,result:null}),{compress:true});}});if(channel==='homeassistant')client.send(JSON.stringify({type:'auth_required',ha_version:'fixture'}),{compress:true});});
  await new Promise(resolve=>mock.listen(0,'127.0.0.1',resolve));record.mockPort=mock.address().port;
