  const config=`schemaVersion: 1\nagent:\n  model: fixture/deterministic\n  maxContextTokens: 65536\n  maxOutputTokens: 8192\nmodel:\n  providers:\n    fixture:\n      protocol: openai\n      url: http://127.0.0.1:${record.mockPort}/v1\n      apiKey: fixture-only\n      models:\n        deterministic:\n          capabilities:\n            supportsToolUse: true\n            maxContextTokens: 65536\n            maxOutputTokens: 8192\ntelemetry:\n  enabled: false\nadapters:\n${adapter}`;fs.writeFileSync(path.join(pilot,'pilotdeck.yaml'),config);
  const env={PATH:process.env.PATH,HOME:home,USERPROFILE:home,CFFIXED_USER_HOME:home,PILOT_HOME:pilot,PILOTDECK_CONFIG_PATH:path.join(pilot,'pilotdeck.yaml'),TMPDIR:dir,LANG:'C',LC_ALL:'C',TZ:'UTC',NODE_NO_WARNINGS:'1',NO_COLOR:'1'};const args=[entry,'server','--host','127.0.0.1','--port','0'];fs.writeFileSync(path.join(dir,'command.json'),json({command:process.execPath,args,env,cwd:project}));
  const child=spawn(process.execPath,args,{env,cwd:project,detached:true,stdio:['ignore','pipe','pipe']});record.pid=child.pid;const stdout=[],stderr=[];child.stdout.on('data',chunk=>{stdout.push(chunk);record.stdout+=chunk.toString()});child.stderr.on('data',chunk=>{stderr.push(chunk);record.stderr+=chunk.toString()});const ended=new Promise(resolve=>child.once('close',(code,signal)=>{record.exit={code,signal};resolve()}));child.once('error',error=>record.scriptError=error.stack);
